def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def to_pair(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default

    def get_pos(key, default=(0, 0)):
        return to_pair(observation.get(key, default), default)

    def step_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def score_cell(cell, src, prefer_far=False):
        cx, cy = cell
        sx, sy = src
        d = abs(cx - sx) + abs(cy - sy)
        return (-d if prefer_far else d)

    env = observation.get("environment_name", "") or "resource_collection"
    sx, sy = get_pos("self_position", (0, 0))
    ox, oy = get_pos("opponent_position", (sx, sy))
    grid_w = observation.get("grid_width", 0) or 0
    grid_h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward((sx, sy), (ox, oy))
        corners = []
        if grid_w > 0 and grid_h > 0:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        target = max(corners, key=lambda c: score_cell(c, (ox, oy), prefer_far=True))
        return step_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda c: score_cell(c, (sx, sy), prefer_far=False))
            return step_toward((sx, sy), best)
        if grid_w > 0 and grid_h > 0:
            mid = (grid_w // 2, grid_h // 2)
            return step_toward((sx, sy), mid)
        return step_away((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    if resources:
        best = min(resources, key=lambda c: score_cell(c, (sx, sy), prefer_far=False))
        return step_toward((sx, sy), best)

    carrying = observation.get("carrying", 0) or observation.get("resource_count", 0) or 0
    if carrying:
        return step_away((sx, sy), (ox, oy))

    if grid_w > 0 and grid_h > 0:
        center = (grid_w // 2, grid_h // 2)
        return step_toward((sx, sy), center)

    return step_away((sx, sy), (ox, oy))

